import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"General","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/general.md","filePath":"user-guide/settings/general.md","lastUpdated":1783954208000}'),n={name:"user-guide/settings/general.md"};function s(r,e,l,h,d,u){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h1><p>Four tabs: <strong>System</strong>, <strong>Search Bar Layout</strong>, <strong>Preview</strong>, and <strong>Search Window</strong>.</p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><ul><li><p><strong>Start SwiftList with Windows</strong> — checkbox, launches SwiftList at sign-in.</p></li><li><p><strong>Run as Administrator</strong> — checkbox, only enabled if the current user account is an administrator. Elevates just the background hotkey-listener process (not the whole app), so the global hotkey isn&#39;t blocked by other elevated (as-admin) foreground applications.</p></li><li><p><strong>Auto check for updates on startup</strong> — checkbox.</p></li><li><p><strong>Auto silent update when a new version is detected</strong> — checkbox, only enabled while the check above is on; downloads and installs updates in the background without prompting.</p></li><li><p><strong>Enable hardware acceleration</strong> — checkbox, on by default. Turning it off forces the quick search window to render in software instead of using Direct3D — this works around NVIDIA Advanced Optimus refusing to hot-switch GPUs while SwiftList is running (only the quick window is affected, not the whole app). Requires restarting SwiftList to take effect.</p></li><li><p><strong>Log level</strong> — dropdown: Error / Warn / Info (default) / Debug. Controls verbosity across the App, Service, and Hook logs (see <a href="./service-status.html">Service Status</a>).</p></li><li><p><strong>Interface language</strong> — dropdown, populated from every installed translation provider (built-in languages plus any a plugin adds).</p></li><li><p><strong>Interface theme</strong> — dropdown: Light, Dark, Nord, Sakura, Cyberpunk from the built-in CoreExtensions plugin, plus Neon Genesis, Sakura Bloom, and Weathering Blue from the bundled AnimeThemes plugin if it&#39;s installed and enabled (any other theme plugin can add more). Hidden while &quot;Follow system light/dark setting&quot; (below) is on, since that takes over which theme applies.</p></li><li><p><strong>Follow system light/dark setting</strong> — checkbox, off by default. When on, SwiftList switches between two themes you pick — one for when Windows is in light mode, one for dark — instead of using a single fixed theme, and updates immediately whenever you toggle Windows&#39; own setting (no restart needed). Reveals two more dropdowns in place of the single theme picker above:</p><ul><li><strong>Light theme</strong> — only lists themes that aren&#39;t dark-flavored.</li><li><strong>Dark theme</strong> — only lists themes that are dark-flavored.</li></ul><p>Each defaults to whichever matching-flavor theme happens to be installed first, since which themes exist at all depends entirely on which theme plugins are installed.</p></li></ul><h2 id="search-bar-layout" tabindex="-1">Search Bar Layout <a class="header-anchor" href="#search-bar-layout" aria-label="Permalink to &quot;Search Bar Layout&quot;">​</a></h2><p>Customizes the size, corner rounding, and on-screen position of the quick search bar:</p><ul><li><strong>Search Bar Width (px)</strong> — range 300–1200px, default 570px.</li><li><strong>Search Bar Height (px)</strong> — range 45–120px, default 55px. This one number also drives the overall UI scale factor (<code>height / 70</code>) for result-row icons and fonts, so a taller search bar scales the whole result list up with it.</li><li><strong>Corner Radius (px)</strong> — range 0–50px, default 8px.</li><li><strong>Result Icon Size (px)</strong> — range 16–64px, default 55px. Result name/path font size scales with this (with a legibility floor), independent of the search bar height above.</li><li><strong>Show clock in search box</strong> — checkbox, off by default. While the search box is empty, replaces the usual &quot;Type to search...&quot; placeholder text with the current date, day of week, and time instead. Disappears the moment you start typing, same as the placeholder it replaces.</li><li><strong>Reset Layout Settings</strong> button — restores all five values above to their defaults.</li></ul><p>Right-clicking the status icon inside the quick window&#39;s search box resets just its on-screen position (not size), re-centering it the same way it centers on first launch.</p><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h2><ul><li><strong>Preview Width (px)</strong> — range 250–900px.</li><li><strong>Preview Height (px)</strong> — range 250–1200px, default sized so the pane isn&#39;t overly tall on a typical display.</li><li><strong>Reset Preview Window Settings</strong> button.</li></ul><p>The preview window ignores the current result count — it&#39;s a fixed size, not a size that grows with content. See <a href="./../actions-and-preview.html">Actions Menu &amp; Preview</a> for how the pane is positioned.</p><h2 id="search-window" tabindex="-1">Search Window <a class="header-anchor" href="#search-window" aria-label="Permalink to &quot;Search Window&quot;">​</a></h2><p>Sets the default size of the full/main search window (the larger window you get from the taskbar or Start Menu shortcut, as opposed to the quick popup — see <a href="./../getting-started.html#the-three-windows">Getting Started</a>):</p><ul><li><strong>Window Width (px)</strong> — range 640–2000px, default 854px.</li><li><strong>Window Height (px)</strong> — range 400–1400px, default 480px. The minimums match the window&#39;s own resize floor, so a configured value is never silently overridden by the window itself.</li><li><strong>Reset Search Window Settings</strong> button.</li></ul><p>Dragging the window&#39;s edge to resize it manually is remembered automatically — the next time you open the window (or open a new one), it comes back at whatever size you last left it at, and this page&#39;s fields update to match. Resizing while maximized doesn&#39;t overwrite the remembered size; only resizing in the normal (non-maximized) state does.</p>',15)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
